import sys
sys.path.insert(0,'/tmp')
from probe import *

def name_bytes(s):
    return encode_name(s)
def cs(s):
    if isinstance(s,str): s=s.encode()
    return bytes([len(s)])+s

# Craft answer based on qtype
def make_rdata(qtype, labels):
    import struct as st
    if qtype==1: return socket.inet_aton("93.184.216.34")
    if qtype==28: return socket.inet_pton(socket.AF_INET6,"2606:2800:220:1:248:1893:25c8:1946")
    if qtype==2: return encode_name("ns1.example.com")
    if qtype==5: return encode_name("alias.example.com")
    if qtype==12: return encode_name("ptr.example.com")
    if qtype==15: return st.pack("!H",10)+encode_name("mail.example.com")
    if qtype==16: return cs("hello world")+cs("second string")
    if qtype==6:
        return encode_name("ns1.example.com")+encode_name("hostmaster.example.com")+st.pack("!IIIII",2020010101,7200,3600,1209600,300)
    if qtype==13: return cs("PC-Intel")+cs("Linux")
    if qtype==33: return st.pack("!HHH",10,5,5060)+encode_name("sipserver.example.com")
    if qtype==257: return bytes([0])+cs("issue")+b"letsencrypt.org"
    if qtype==29:
        # LOC: version0, size 0x12?, etc. Latitude: (degrees?) Compute: 2^31 + ... we'll set raw and see output
        # version=0,size=0x10 (1m?), horiz=0x16, vert=0x13, lat, lon, alt
        # latitude  51deg 31'?? Lets use known example: ??? just set 2**31
        return bytes([0,0x12,0x16,0x13])+st.pack("!III", (1<<31)+1000000, (1<<31)-2000000, 10000000+500000)
    if qtype==35:
        return st.pack("!HH",100,10)+cs("S")+cs("SIP+D2U")+cs("")+encode_name("srv.example.com")
    if qtype==44:
        return bytes([2,1])+bytes.fromhex("123456789abcdef0123456789abcdef012345678")
    if qtype==52:
        return bytes([3,1,1])+bytes.fromhex("abcdef0123456789"*4)
    # generic fallback
    return b"\x01\x02\x03\x04\x05"

def responder(req):
    labels,off=parse_name(req,12)
    qtype,qclass=struct.unpack("!HH", req[off:off+4])
