import sys; sys.path.insert(0,'/tmp')
from probe import *
import time

def raw_responder(packet_builder):
    def responder(req):
        txid=req[:2]
        return packet_builder(txid, req)
    return responder

def packet(txid, qname, ans_raw_list, qtype=1):
    header=txid+b"\x81\x80"+struct.pack("!HHHH",1,len(ans_raw_list),0,0)
    q=encode_name(qname)+struct.pack("!HH",qtype,1)
    return header+q+b"".join(ans_raw_list)

def rr(name_raw, typ, ttl, rdata, rdlen_override=None):
    rdlen=len(rdata) if rdlen_override is None else rdlen_override
    return name_raw+struct.pack("!HHIH",typ,1,ttl,rdlen)+rdata

tests=[]
# NS with extra bytes in rdata after name and another genuine answer after
def b1(txid,req):
    a1=rr(b"\xc0\x0c",2,3600,encode_name("ns1.example.com")+b"XYZ", rdlen_override=len(encode_name("ns1.example.com")+b"XYZ"))
    a2=rr(b"\xc0\x0c",1,3600,socket.inet_aton("1.2.3.4"))
    return packet(txid,"example.com",[a1,a2])
tests.append(("NS extra XYZ in rdlen then A",b1))
# NS with rdlen shorter than encoded name (rdlen=2 but bytes of name present in packet followed by A answer)
def b2(txid,req):
    name=encode_name("ns1.example.com")
    a1=rr(b"\xc0\x0c",2,3600,name, rdlen_override=2)
    a2=rr(b"\xc0\x0c",1,3600,socket.inet_aton("1.2.3.4"))
    return packet(txid,"example.com",[a1,a2])
tests.append(("NS rdlen=2 but full name bytes",b2))
# TXT string length smaller than actual bytes?
def b3(txid,req):
    # txt rdata: cs hello + extra 3 bytes (not valid charstr) included in rdlen
    rd=bytes([5])+b"hello"+b"XYZ"
    a1=rr(b"\xc0\x0c",16,3600,rd)
    a2=rr(b"\xc0\x0c",1,3600,socket.inet_aton("1.2.3.4"))
    return packet(txid,"example.com",[a1,a2])
tests.append(("TXT extra XYZ after string",b3))
# TXT rdlen shorter than char string claims, but bytes present
def b4(txid,req):
    rd=bytes([5])+b"hello"
    a1=rr(b"\xc0\x0c",16,3600,rd,rdlen_override=3)
    a2=rr(b"\xc0\x0c",1,3600,socket.inet_aton("1.2.3.4"))
    return packet(txid,"example.com",[a1,a2])
tests.append(("TXT rdlen 3 vs 6 bytes",b4))
# Unknown bytes record extra correctness uses rdlen slice presumably
def b5(txid,req):
    a1=rr(b"\xc0\x0c",99,3600,b"\x01\x02\x03",rdlen_override=2) # packet next answer starts after 3 bytes physically, but parser should consume only 2 if slice? Then next rr parsing misalign if respects actual physical...
    a2=rr(b"\xc0\x0c",1,3600,socket.inet_aton("1.2.3.4"))
    return packet(txid,"example.com",[a1,a2])
tests.append(("Unknown rdlen 2 but 3 bytes before next",b5))
# A record rdlen 4 but only 2 bytes then next answer physically after 2 (parser length check on rdlen=4 passes, then reads next 4 bytes which are next RR name/type and misaligns)
def b6(txid,req):
    a1=name=b"\xc0\x0c"+struct.pack("!HHIH",1,1,3600,4)+b"\x01\x02"
    a2=rr(b"\xc0\x0c",1,3600,socket.inet_aton("1.2.3.4"))
    return packet(txid,"example.com",[a1,a2])
tests.append(("A rdlen 4 but only 2 physical then next",b6))
# TXT trailing extra bytes after all RRs (trailing garbage in packet)
def b7(txid,req):
    a1=rr(b"\xc0\x0c",1,3600,socket.inet_aton("1.2.3.4"))
    return packet(txid,"example.com",[a1])+b"GARBAGE"
tests.append(("trailing garbage",b7))
