import subprocess, pty, os
def pipe(args, env=None):
    e=dict(os.environ)
    if env: e.update(env)
    p=subprocess.run(['./executable']+args,capture_output=True,env=e)
    print("pipe",args,env, repr(p.stdout[:200]))
def tty(args, env=None):
    pid,fd=pty.fork()
    if pid==0:
        if env:
            for k,v in env.items(): os.environ[k]=v
        os.execv("./executable",["./executable"]+args)
    data=b""
    while True:
        try:
            d=os.read(fd,4096)
            if not d: break
            data+=d
        except OSError: break
    os.waitpid(pid,0)
    print("tty",args,env,repr(data[:300]))

for a in [["--help"],["--help","--color=always"],["--help","--color=never"],["--help","--color=automatic"],["--version","--color=always"],["--version","--color=never"]]:
