for env in [{"TERM":"dumb"},{"TERM":""},{"NO_COLOR":"1"},{"CLICOLOR":"0"},{"CLICOLOR_FORCE":"1"}]:
    pipe(["--version"],env); tty(["--version"],env)
# Also normal query pipe with CLICOLOR_FORCE etc maybe later
