        while b"\r\n\r\n" not in data: data+=ssock.recv(4096)
        head,body=data.split(b"\r\n\r\n",1)
        # content len
        cl=int([l.split(b':')[1] for l in head.split(b"\r\n") if l.lower().startswith(b'content-length')][0])
        while len(body)<cl: body+=ssock.recv(4096)
        resp_dns=build_response(body,[("PTR_QUESTION",1,1,60,socket.inet_aton("8.8.8.8"))])
        full=b"HTTP/1.1 200 OK\r\nContent-Type: application/dns-message\r\nContent-Length: "+str(len(resp_dns)).encode()+b"\r\nConnection: close\r\n\r\n"+resp_dns
        payloads=[]
        for c in chunks:
            if isinstance(c,int): payloads.append(full[:c]); full=full[c:]
            elif c=="REST": payloads.append(full); full=b""
            else: payloads.append(c)
        if full: payloads.append(full)
        for pl in payloads:
            if pl: ssock.sendall(pl)
            time.sleep(delay)
        if close_mode=="fdclose":
            try:
                fd=ssock.fileno(); ssock.detach(); os.close(fd)
            except Exception as e: print("close err",e)
        elif close_mode=="unwrap":
            try: ssock.unwrap().close()
            except Exception as e: print("unwrap err",e)
        elif close_mode=="shutdown":
            try: ssock.shutdown(socket.SHUT_RDWR)
            except Exception as e: print("shutdown err",e)
            ssock.close()
        raw.close()
    t=threading.Thread(target=serve,daemon=True);t.start();time.sleep(0.2)
    p=subprocess.Popen(['./executable','-H','-n','https://127.0.0.1/dns','example.com'],stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,env={**os.environ,"SSL_CERT_FILE":"/tmp/certs/cert.pem","DOG_DEBUG":"1"})
