    except subprocess.TimeoutExpired: p.kill(); out,err=p.communicate(); status="TIMEOUT"
    clean=re.sub(r'\x1b\[[0-9;]*m','',err)
    print(name,close_mode,status,p.returncode,repr(out),[l.strip() for l in clean.splitlines() if 'dns_transport::https' in l or 'Error' in l])
    t.join(timeout=2); time.sleep(0.5)

