 resp=append(resp,q[12:]...)
 resp=append(resp,0xc0,0x0c,0,1,0,1,0,0,0,60,0,4,8,8,8,8)
 full:=fmt.Sprintf("HTTP/1.1 200 OK\r\nContent-Type: application/dns-message\r\nContent-Length: %d\r\nConnection: close\r\n\r\n",len(resp))
 payload:=append([]byte(full),resp...)
 switch(mode){
 case "empty":
   // write nothing
 case "partialheaders":
   conn.Write(payload[:10])
 case "shortbody":
   conn.Write(payload[:120])
 case "garbage":
   conn.Write([]byte("hello\r\n\r\n"))
 case "lf":
   conn.Write([]byte("HTTP/1.1 200 OK\nContent-Length: 0\n\n"))
 default:
   conn.Write(payload)
 }
 // force close underlying
 if tc,ok:=conn.(*tls.Conn); ok { tc.NetConn().Close() }
 conn.Close()
 // avoid unused io
 _=io.EOF
 ln.Close()
 var _ net.Addr
}
