#!/usr/bin/env python3
"""Independent reimplementation of the dog command-line DNS client."""

import base64
import errno
import ipaddress
import os
import random
import re
import signal
import socket
import ssl
import stringprep
import struct
import sys
import time
import unicodedata

# ---------------------------------------------------------------------------
# Small output helpers
# ---------------------------------------------------------------------------

def _write_fd(fd, data):
    if isinstance(data, str):
        data = data.encode("utf-8", "surrogateescape")
    try:
        view = memoryview(data)
        while view:
            written = os.write(fd, view)
            if written == 0:
                break
            view = view[written:]
    except BrokenPipeError:
        # Match a native program whose output pipe has gone away without a
        # Python traceback.  Further writes will also fail; exiting through
        # the normal path is not really observable in that situation.
        try:
            os._exit(1)
        except Exception:
            pass

def out_write(data):
    _write_fd(1, data)

def err_write(data):
    _write_fd(2, data)

# ---------------------------------------------------------------------------
# Rust-flavoured string debug/escaping helpers
# ---------------------------------------------------------------------------

def _rust_printable(ch):
    if ch == " ":
        return True
    cat = unicodedata.category(ch)
    # Rust's core printable tables (used by escape_debug) consider letters,
    # numbers, punctuation and symbols printable, as well as spacing marks,
    # but not non-spacing/enclosing marks and not format/control/private or
    # unassigned codepoints.
    if cat and cat[0] in "LNPS":
        return True
    if cat == "Mc":
        return True
    return False

def rust_escape_debug_char(ch):
    if ch == "\0":
        return "\\0"
    if ch == "\t":
        return "\\t"
    if ch == "\r":
        return "\\r"
    if ch == "\n":
        return "\\n"
    if ch == "\\":
        return "\\\\"
    if ch == '"':
        return '\\"'
    if _rust_printable(ch):
        return ch
    return "\\u{%x}" % ord(ch)

def rust_debug_str(s):
    return '"' + "".join(rust_escape_debug_char(ch) for ch in s) + '"'

def _try_decode_utf8_at(data, pos):
    """Return (char, byte-length) for a valid UTF-8 sequence at data[pos:], or None."""
    b0 = data[pos]
    if b0 < 0x80:
        return chr(b0), 1
    if 0xC2 <= b0 <= 0xDF:
        need = 2
    elif 0xE0 <= b0 <= 0xEF:
        need = 3
    elif 0xF0 <= b0 <= 0xF4:
        need = 4
    else:
        return None
    chunk = data[pos:pos + need]
    if len(chunk) < need:
        return None
    try:
        text = chunk.decode("utf-8")
    except UnicodeDecodeError:
        return None
    if len(text) != 1:
        return None
    return text, need

def rust_debug_osstring(data):
    out = ['"']
    pos = 0
    while pos < len(data):
        decoded = _try_decode_utf8_at(data, pos)
        if decoded is None:
            out.append("\\x%02X" % data[pos])
            pos += 1
        else:
            ch, n = decoded
            out.append(rust_escape_debug_char(ch))
            pos += n
    out.append('"')
    return "".join(out)

def quote_byte_string(data):
    """Quote raw bytes the way the reference does for textual DNS strings."""
    out = ['"']
    for byte in data:
        if byte == 0x22:  # "
            out.append('\\"')
        elif byte == 0x5C:  # backslash
            out.append("\\\\")
        elif 0x20 <= byte < 0x80:
            out.append(chr(byte))
        else:
            out.append("\\" + str(byte))
    out.append('"')
    return "".join(out)

def lossy_utf8(data):
    return data.decode("utf-8", "replace")

# A tiny pretty-printer for the subset of Rust's {:#?} output used here.
class _Struct:
    def __init__(self, name, fields):
        self.name = name
        self.fields = fields  # list of (name, node)

class _TupleVariant:
    def __init__(self, name, args):
        self.name = name
        self.args = args

class _Tuple:
    def __init__(self, args):
        self.args = args

class _List:
    def __init__(self, items):
        self.items = items

class _Bare:
    def __init__(self, text):
        self.text = text

def _debug_lines(node, indent):
    pad = "    " * indent
    if isinstance(node, _Bare):
        return [pad + node.text]
    if isinstance(node, str):
        return [pad + rust_debug_str(node)]
    if isinstance(node, bool):
        return [pad + ("true" if node else "false")]
    if isinstance(node, int):
        return [pad + str(node)]
    if isinstance(node, _List):
        if not node.items:
            return [pad + "[]"]
        lines = [pad + "["]
        for item in node.items:
            sub = _debug_lines(item, indent + 1)
            sub[-1] += ","
            lines.extend(sub)
        lines.append(pad + "]")
        return lines
    if isinstance(node, _Tuple):
        if not node.args:
            return [pad + "()"]
        lines = [pad + "("]
        for item in node.args:
            sub = _debug_lines(item, indent + 1)
            sub[-1] += ","
            lines.extend(sub)
        lines.append(pad + ")")
        return lines
    if isinstance(node, _TupleVariant):
        if not node.args:
            return [pad + node.name]
        lines = [pad + node.name + "("]
        for item in node.args:
            sub = _debug_lines(item, indent + 1)
            sub[-1] += ","
            lines.extend(sub)
        lines.append(pad + ")")
        return lines
    if isinstance(node, _Struct):
        if not node.fields:
            return [pad + node.name + " {}"]
        lines = [pad + node.name + " {"]
        for key, value in node.fields:
            sub = _debug_lines(value, indent + 1)
            # Splice "key: " in front of the first line of the value.
            first = sub[0]
            stripped = first[len("    " * (indent + 1)):]
            sub[0] = "    " * (indent + 1) + key + ": " + stripped
            sub[-1] += ","
            lines.extend(sub)
        lines.append(pad + "}")
        return lines
    raise TypeError("unsupported debug node %r" % (node,))

def rust_debug_pretty(node):
    return "\n".join(_debug_lines(node, 0))

# ---------------------------------------------------------------------------
# Logging (DOG_DEBUG)
# ---------------------------------------------------------------------------

_LOG_LEVELS = {"ERROR": 1, "WARN": 2, "INFO": 3, "DEBUG": 4, "TRACE": 5}
_LOG_COLOURS = {
    "ERROR": "\x1b[31m",
    "WARN": "\x1b[33m",
    "INFO": "\x1b[36m",
    "DEBUG": "\x1b[34m",
    "TRACE": "\x1b[38;5;245m",
}
_log_max = 0

def setup_logging():
    global _log_max
    value = os.environb.get(b"DOG_DEBUG") if hasattr(os, "environb") else None
    if value is None:
        env_value = os.environ.get("DOG_DEBUG")
        value = None if env_value is None else env_value.encode("utf-8", "surrogateescape")
    if value is None or len(value) == 0:
        _log_max = 0
    elif value == b"trace":
        _log_max = 5
    else:
        _log_max = 4

def log_enabled(level):
    return _LOG_LEVELS[level] <= _log_max

def log_msg(level, target, message):
    if not log_enabled(level):
        return
    prefix = "\x1b[38;5;243m[\x1b[0m"
    suffix = "\x1b[38;5;243m]\x1b[0m"
    err_write("%s%s%s\x1b[0m %s%s %s\n" % (prefix, _LOG_COLOURS[level], level, target, suffix, message))

def log_error(target, message):
    log_msg("ERROR", target, message)

def log_warn(target, message):
    log_msg("WARN", target, message)

def log_info(target, message):
    log_msg("INFO", target, message)

def log_debug(target, message):
    log_msg("DEBUG", target, message)

def log_trace(target, message):
    log_msg("TRACE", target, message)

# ---------------------------------------------------------------------------
# Panics (a couple of places in the reference abort on bad input)
# ---------------------------------------------------------------------------

def rust_panic(location, message):
    pid = os.getpid()
    backtrace = os.environ.get("RUST_BACKTRACE")
    if backtrace is None:
        backtrace = os.environ.get("RUST_LIB_BACKTRACE")
