class LabelEncodeError(Exception):
    def __init__(self, errors):
        Exception.__init__(self, ", ".join(errors))
        self.errors = errors

_DEVIATIONS = {"\u00df", "\u03c2", "\u200c", "\u200d"}
_ASCII_LOWER_TABLE = str.maketrans("ABCDEFGHIJKLMNOPQRSTUVWXYZ", "abcdefghijklmnopqrstuvwxyz")

def _is_ascii_text(s):
    return all(ord(ch) < 128 for ch in s)

def _is_disallowed_char(ch):
    if ord(ch) < 128 or ch in _DEVIATIONS:
        return False
    if ch == "\u2024":
        return True
    if unicodedata.category(ch) == "Cn":
        return True
    try:
        return (
            stringprep.in_table_c12(ch) or stringprep.in_table_c22(ch) or
            stringprep.in_table_c3(ch) or stringprep.in_table_c4(ch) or
            stringprep.in_table_c5(ch) or stringprep.in_table_c6(ch) or
            stringprep.in_table_c7(ch) or stringprep.in_table_c8(ch) or
            stringprep.in_table_c9(ch)
        )
    except Exception:
        return False

def _map_unicode_label(label):
    out = []
    for ch in label:
        if ch in _DEVIATIONS:
            out.append(ch)
        elif ch in ("\u3002", "\uff0e", "\uff61"):
            out.append(".")
        elif stringprep.in_table_b1(ch):
            continue
        else:
            out.append(stringprep.map_table_b2(ch))
    return unicodedata.normalize("NFKC", "".join(out))

def _unicode_label_errors(mapped, raw_had_extra_disallowed=False):
    errors = []
    disallowed = raw_had_extra_disallowed or any(_is_disallowed_char(ch) for ch in mapped)
    if disallowed:
        errors.append("DissallowedCharacter")
    validity = False
    if mapped:
        if unicodedata.category(mapped[0])[0] == "M":
            validity = True
        if mapped[0] == "-" or mapped[-1] == "-":
            validity = True
        if mapped[:4].translate(_ASCII_LOWER_TABLE) == "xn--":
            validity = True
        if disallowed:
            validity = True
    if validity:
        errors.append("ValidityCriteria")
    return errors

def _unicode_label_to_ascii(segment):
    raw_extra = ("\u2024" in segment)
    mapped = _map_unicode_label(segment)
    if mapped == "":
        raise LabelEncodeError(["TooShortForDns"])
    errors = _unicode_label_errors(mapped, raw_extra)
    if errors:
        raise LabelEncodeError(errors)
    if _is_ascii_text(mapped):
        result = mapped
    else:
        result = "xn--" + mapped.encode("punycode").decode("ascii")
    if len(result) > 63:
        raise LabelEncodeError(["TooLongForDns"])
    if len(result) == 0:
        raise LabelEncodeError(["TooShortForDns"])
    return result

def _ace_label_to_ascii(lower_label):
    if len(lower_label) > 63:
        raise LabelEncodeError(["TooLongForDns"])
    suffix = lower_label[4:]
    if suffix == "":
        raise LabelEncodeError(["TooShortForDns"])
    # Punycode in an A-label consists only of LDH characters.
    if re.fullmatch(r"[a-z0-9-]*", suffix) is None:
        raise LabelEncodeError(["PunycodeError", "TooShortForDns"])
    try:
        decoded = suffix.encode("ascii").decode("punycode")
    except Exception:
        raise LabelEncodeError(["PunycodeError", "TooShortForDns"])
    if decoded == "":
        raise LabelEncodeError(["PunycodeError", "TooShortForDns"])
    # The decoded U-label must itself be valid and already in mapped form.
    mapped = _map_unicode_label(decoded)
    validity = False
    if mapped != decoded:
        validity = True
    if any(_is_disallowed_char(ch) for ch in decoded):
        validity = True
    if decoded:
        if unicodedata.category(decoded[0])[0] == "M":
            validity = True
        if decoded[0] == "-" or decoded[-1] == "-":
            validity = True
    if validity:
        raise LabelEncodeError(["ValidityCriteria"])
    if _is_ascii_text(decoded):
        result = decoded
    else:
        result = "xn--" + decoded.encode("punycode").decode("ascii")
    if len(result) > 63:
        raise LabelEncodeError(["TooLongForDns"])
    if len(result) == 0:
        raise LabelEncodeError(["TooShortForDns"])
    return result

def _label_to_ascii(segment):
    if _is_ascii_text(segment):
        lowered = segment.translate(_ASCII_LOWER_TABLE)
        if lowered.startswith("xn--"):
            return _ace_label_to_ascii(lowered)
        if len(lowered) > 63:
            raise LabelEncodeError(["TooLongForDns"])
        if lowered.startswith("-") or lowered.endswith("-"):
            raise LabelEncodeError(["ValidityCriteria"])
        return lowered
    return _unicode_label_to_ascii(segment)

