        segment_nodes = [_Tuple([len(segment.encode("utf-8", "surrogateescape")), segment]) for segment in self.segments]
        return _Struct("Labels", [("segments", _List(segment_nodes))])

    def wire_bytes(self):
        out = bytearray()
        for segment in self.segments:
            raw = segment.encode("utf-8", "surrogateescape")
            out.append(len(raw))
            out.extend(raw)
        out.append(0)
        return bytes(out)

