_DUPLICATE_ORDER = [
    "edns", "txid", "udp", "tcp", "tls", "https", "color", "colour",
    "json", "seconds", "short", "time", "version", "help",
]
_OPTS_BY_SHORT = dict((o.short, o) for o in _OPTION_DEFS if o.short is not None)
_OPTS_BY_LONG = dict((o.long, o) for o in _OPTION_DEFS if o.long is not None)
_OPTS_BY_CANONICAL = dict((o.canonical, o) for o in _OPTION_DEFS)

class Matches(object):
    def __init__(self):
        self.values = {}   # canonical -> [str or None]
        self.free = []

    def present(self, canonical):
        return canonical in self.values

    def opt_str(self, canonical):
        values = self.values.get(canonical)
        if not values:
            return None
        return values[0]

    def opt_strs(self, canonical):
        return list(self.values.get(canonical, []))

def _find_long_option(name):
    if len(name) == 1:
        return _OPTS_BY_SHORT.get(name)
    return _OPTS_BY_LONG.get(name)

def getopts_parse(args):
    matches = Matches()

    def record(opt, value):
        matches.values.setdefault(opt.canonical, []).append(value)

    only_free = False
    i = 0
    while i < len(args):
        arg = args[i]
        if only_free:
            matches.free.append(arg)
        elif arg == "--":
            only_free = True
        elif arg.startswith("--"):
            token = arg[2:]
            if "=" in token:
                name, value = token.split("=", 1)
            else:
                name, value = token, None
            opt = _find_long_option(name)
            if opt is None:
                raise GetoptsFail("Unrecognized option: '%s'" % name)
            if not opt.takes_arg:
                if value is not None:
                    raise GetoptsFail("Option '%s' does not take an argument" % name)
                record(opt, None)
            else:
                if value is not None:
                    record(opt, value)
                else:
                    if i + 1 >= len(args):
                        raise GetoptsFail("Argument to option '%s' missing" % name)
                    i += 1
                    record(opt, args[i])
        elif arg.startswith("-") and len(arg) > 1:
            chars = arg[1:]
            for pos, ch in enumerate(chars):
                opt = _OPTS_BY_SHORT.get(ch)
                if opt is None:
                    raise GetoptsFail("Unrecognized option: '%s'" % ch)
                if opt.takes_arg:
                    remainder = chars[pos + 1:]
                    if remainder != "":
                        record(opt, remainder)
                    else:
                        if i + 1 >= len(args):
                            raise GetoptsFail("Argument to option '%s' missing" % ch)
                        i += 1
                        record(opt, args[i])
                    break
                record(opt, None)
        else:
            matches.free.append(arg)
        i += 1

    for canonical in _DUPLICATE_ORDER:
        if len(matches.values.get(canonical, [])) > 1:
            raise GetoptsFail("Option '%s' given more than once" % canonical)
    return matches

# Numeric parsing helpers matching Rust's integer parsing.

def _parse_rust_u16(text):
    if re.fullmatch(r"\+?[0-9]+", text) is None:
        return None
    try:
        value = int(text, 10)
    except Exception:
        return None
    if value > 65535:
        return None
    return value

def _parse_rust_u16_hex(text):
    if re.fullmatch(r"\+?[0-9a-fA-F]+", text) is None:
        return None
    try:
        value = int(text, 16)
    except Exception:
        return None
    if value > 65535:
        return None
    return value

def _rust_u16_error_kind(text, base=10):
    if text == "":
        return "Empty"
    pattern = r"\+?[0-9]+" if base == 10 else r"\+?[0-9a-fA-F]+"
    if re.fullmatch(pattern, text) is None:
        return "InvalidDigit"
    value = int(text, base)
    if value > 65535:
        return "PosOverflow"
    return None

def _ascii_upper(s):
    return s.translate(str.maketrans("abcdefghijklmnopqrstuvwxyz", "ABCDEFGHIJKLMNOPQRSTUVWXYZ"))

def parse_query_type(text):
    if _ascii_upper(text) == "OPT" and _is_ascii_text(text):
        raise OptionsError("OPT request is sent by default (see -Z flag)")
    if _is_ascii_text(text):
        upper = _ascii_upper(text)
        if upper in TYPE_NAME_TO_CODE:
            return TYPE_NAME_TO_CODE[upper]
    numeric = _parse_rust_u16(text)
    if numeric is not None:
        return numeric
    raise OptionsError("Invalid query type %s" % rust_debug_str(text))

def parse_query_class(text):
    if _is_ascii_text(text):
        upper = _ascii_upper(text)
        if upper in CLASS_NAME_TO_CODE:
            return CLASS_NAME_TO_CODE[upper]
    numeric = _parse_rust_u16(text)
    if numeric is not None:
        return numeric
    raise OptionsError("Invalid query class %s" % rust_debug_str(text))

def parse_txid(text):
    value = None
    if text.startswith("0x"):
        value = _parse_rust_u16_hex(text[2:])
    else:
        value = _parse_rust_u16(text)
    if value is None:
        raise OptionsError("Invalid transaction ID %s" % rust_debug_str(text))
    return value

