            stringprep.in_table_c3(ch) or stringprep.in_table_c4(ch) or
            stringprep.in_table_c5(ch) or stringprep.in_table_c6(ch) or
            stringprep.in_table_c7(ch) or stringprep.in_table_c8(ch) or
            stringprep.in_table_c9(ch)
