    try:
        decoded = suffix.encode("ascii").decode("punycode")
    except Exception:
        raise LabelEncodeError(["PunycodeError", "TooShortForDns"])
    if decoded == "":
        raise LabelEncodeError(["PunycodeError", "TooShortForDns"])
    # The decoded U-label must itself be valid and already in mapped form.
    mapped = _map_unicode_label(decoded)
    validity = False
    if mapped != decoded:
