        result = decoded
    else:
        result = "xn--" + decoded.encode("punycode").decode("ascii")
    if len(result) > 63:
        raise LabelEncodeError(["TooLongForDns"])
    if len(result) == 0:
        raise LabelEncodeError(["TooShortForDns"])
