def _colour_choice_from_matches(matches):
    raw = None
    if matches.present("color"):
        raw = matches.opt_str("color")
    elif matches.present("colour"):
        raw = matches.opt_str("colour")
    if raw == "always":
        return "Always"
    if raw == "never":
        return "Never"
    return "Automatic"

def should_use_colour(choice):
    if choice == "Always":
        return True
    if choice == "Never":
        return False
    # Automatic
    if hasattr(os, "environb"):
        if b"NO_COLOR" in os.environb:
            return False
    elif "NO_COLOR" in os.environ:
        return False
    try:
        return os.isatty(1)
    except Exception:
        return False

