class ParsedMode(object):
    def __init__(self, kind, colour_choice="Automatic", options=None):
        self.kind = kind  # "version" | "help" | "nodomains" | "live"
        self.colour_choice = colour_choice
        self.options = options

def parse_options(argv):
    matches = getopts_parse(argv)
    colour_choice = _colour_choice_from_matches(matches)
    if matches.present("version"):
        return ParsedMode("version", colour_choice)
    if matches.present("help"):
        return ParsedMode("help", colour_choice)

    opts = DogOptions()
    opts.colour_choice = colour_choice

    # Sending options are validated, in this order, before the query inputs.
    edns_value = matches.opt_str("edns") if matches.present("edns") else None
    if edns_value is not None:
        if edns_value in ("disable", "hide", "show"):
            opts.edns = edns_value
        else:
            raise OptionsError("Invalid EDNS setting %s" % rust_debug_str(edns_value))

    if matches.present("txid"):
        opts.txid = parse_txid(matches.opt_str("txid"))

    for tweak in matches.opt_strs("Z"):
        if tweak == "aa":
            opts.tweak_aa = True
        elif tweak == "ad":
            opts.tweak_ad = True
        elif tweak == "cd":
            opts.tweak_cd = True
        elif tweak.startswith("bufsize="):
            number = _parse_rust_u16(tweak[len("bufsize="):])
            if number is None:
                raise OptionsError("Invalid protocol tweak %s" % rust_debug_str(tweak))
            opts.tweak_bufsize = number
        else:
            raise OptionsError("Invalid protocol tweak %s" % rust_debug_str(tweak))

    # Query inputs: explicit options first (in the order query, type, class,
    # nameserver), then the free arguments in their own order.
    for query in matches.opt_strs("query"):
        opts.domains.append(encode_labels(query))
    for type_text_value in matches.opt_strs("type"):
        opts.record_types.append(parse_query_type(type_text_value))
    for class_text_value in matches.opt_strs("class"):
        opts.classes.append(parse_query_class(class_text_value))
    for nameserver in matches.opt_strs("nameserver"):
        opts.resolvers.append(Resolver(False, nameserver))

    for argument in matches.free:
        if argument.startswith("@"):
            nameserver = argument[1:]
            log_trace("dog::options", "Got nameserver -> %s" % rust_debug_str(nameserver))
            opts.resolvers.append(Resolver(False, nameserver))
        elif _is_single_word_argument(argument):
            upper = _ascii_upper(argument)
            if upper == "OPT":
                raise OptionsError("OPT request is sent by default (see -Z flag)")
            if upper in TYPE_NAME_TO_CODE:
                log_trace("dog::options", "Got qtype -> %s" % rust_debug_str(argument))
                opts.record_types.append(TYPE_NAME_TO_CODE[upper])
            elif upper in CLASS_NAME_TO_CODE:
                log_trace("dog::options", "Got qclass -> %s" % rust_debug_str(argument))
                opts.classes.append(CLASS_NAME_TO_CODE[upper])
            else:
                log_trace("dog::options", "Got single-word domain -> %s" % rust_debug_str(argument))
                opts.domains.append(encode_labels(argument))
        else:
            log_trace("dog::options", "Got domain -> %s" % rust_debug_str(argument))
            opts.domains.append(encode_labels(argument))

    transports = []
    if matches.present("https"):
        transports.append("https")
    if matches.present("tls"):
        transports.append("tls")
    if matches.present("tcp"):
        transports.append("tcp")
    if matches.present("udp"):
        transports.append("udp")

    if transports == ["https"] and not opts.resolvers:
        raise OptionsError("You must pass a URL as a nameserver when using --https")

    opts.transport_types = transports if transports else ["automatic"]
    if not opts.record_types:
        opts.record_types = [1]
    if not opts.classes:
        opts.classes = [1]
    if not opts.resolvers:
        opts.resolvers = [Resolver(True)]

    opts.measure_time = matches.present("time")
    opts.format_durations = not matches.present("seconds")
    if matches.present("short"):
        opts.format_mode = "short"
    elif matches.present("json"):
        opts.format_mode = "json"
    else:
        opts.format_mode = "text"

    if not opts.domains:
        return ParsedMode("nodomains", colour_choice, opts)
    return ParsedMode("live", colour_choice, opts)

