        # certificate verification stack; this is the common shape.
        detail = verify_message or message
        return ("error:1416F086:SSL routines:tls_process_server_certificate:"
                "certificate verify failed:ssl/statem/statem_clnt.c:1913: (%s)" % detail)
    if "certificate verify failed" in lower or verify_message:
        detail = verify_message
        if not detail:
            # Python messages look like "[SSL: CERTIFICATE_VERIFY_FAILED]
            # certificate verify failed: self signed certificate (_ssl.c:...)".
            match = re.search(r"certificate verify failed: ([^(]+?)(?: \(|$)", message, re.IGNORECASE)
            detail = match.group(1).strip() if match else "certificate verify failed"
        return ("error:1416F086:SSL routines:tls_process_server_certificate:"
                "certificate verify failed:ssl/statem/statem_clnt.c:1913: (%s)" % detail)
    if "wrong version number" in lower:
        return ("error:1408F10B:SSL routines:ssl3_get_record:wrong version number:"
                "ssl/record/ssl3_record.c:331:")
    if "packet length too long" in lower:
        return ("error:1408F10B:SSL routines:ssl3_get_record:packet length too long:"
                "ssl/record/ssl3_record.c:331:")
    if "unknown protocol" in lower:
        return ("error:1408F10B:SSL routines:ssl3_get_record:unknown protocol:"
                "ssl/record/ssl3_record.c:331:")
