    global _tls_context
    if _tls_context is None:
        context = ssl.create_default_context(ssl.Purpose.SERVER_AUTH)
        try:
            context.minimum_version = ssl.TLSVersion.TLSv1
        except Exception:
            pass
        _tls_context = context
    return _tls_context

