    log_info("dns_transport::tcp", "Waiting to receive...")
    try:
        first = _stream_recv(stream, 4096)
    except Exception as exc:
        if tls_stream and isinstance(exc, ssl.SSLError):
            raise Failure("tls", _map_tls_error(exc))
        if isinstance(exc, OSError):
            raise _network_failure(exc)
        raise
    if len(first) == 0:
        log_warn("dns_transport::tcp", "Received no bytes!")
        raise Failure("network", "Truncated response")
    if len(first) == 1:
        log_info("dns_transport::tcp", "Received one byte of data")
        try:
            second = _stream_recv(stream, 4095)
        except Exception as exc:
            if tls_stream and isinstance(exc, ssl.SSLError):
                raise Failure("tls", _map_tls_error(exc))
            if isinstance(exc, OSError):
                raise _network_failure(exc)
            raise
        if len(second) == 0:
            log_warn("dns_transport::tcp", "Received no bytes the second time!")
            raise Failure("network", "Truncated response")
        data = bytearray(first + second)
    else:
        log_info("dns_transport::tcp", "Received %d bytes of data" % len(first))
        data = bytearray(first)

    declared = (data[0] << 8) | data[1]
    payload_length = len(data) - 2
    if payload_length == declared:
        log_debug("dns_transport::tcp", "We have enough bytes")
    else:
        log_debug("dns_transport::tcp", "We need to read %d bytes total" % declared)
        while payload_length < declared:
            try:
                chunk = _stream_recv(stream, 4096)
            except Exception as exc:
                if tls_stream and isinstance(exc, ssl.SSLError):
                    raise Failure("tls", _map_tls_error(exc))
                if isinstance(exc, OSError):
                    raise _network_failure(exc)
                raise
            log_info("dns_transport::tcp", "Received further %d bytes of data (of %d)" % (len(chunk), declared))
            data.extend(chunk)
            payload_length += len(chunk)
            # Mirror the reference here: a zero-length read does not stop
            # this loop.
    return bytes(data[2:])

