        log_info("dns_transport::udp", "Sending %d bytes of data to %s over UDP" % (len(packet), resolver_str))
        try:
            written = sock.send(packet)
        except OSError as exc:
            raise _network_failure(exc)
        log_debug("dns_transport::udp", "Wrote %d bytes" % written)
        log_info("dns_transport::udp", "Waiting to receive...")
        try:
            data = sock.recv(4096)
        except OSError as exc:
            raise _network_failure(exc)
        log_info("dns_transport::udp", "Received %d bytes of data" % len(data))
        return data
    finally:
        try:
            sock.close()
        except Exception:
            pass

def send_over_tcp(packet, resolver):
    resolver_str = resolve_resolver_string(resolver)
    log_info("dns_transport::tcp", "Opening TCP stream")
    address_text = _with_default_port(resolver_str, 53)
    addresses = _str_to_addresses(address_text)
    sock = _connect_stream(addresses)
    try:
        log_debug("dns_transport::tcp", "Opened")
        payload = struct.pack("!H", len(packet)) + packet
        log_info("dns_transport::tcp", "Sending %d bytes of data to %s over TCP" % (len(payload), rust_debug_str(address_text)))
        try:
            written = sock.send(payload)
        except OSError as exc:
            raise _network_failure(exc)
        log_debug("dns_transport::tcp", "Wrote %d bytes" % written)
        return _receive_tcp_stream(sock, tls_stream=False)
    finally:
        try:
            sock.close()
        except Exception:
            pass

def send_over_tls(packet, resolver):
    resolver_str = resolve_resolver_string(resolver)
    log_info("dns_transport::tls", "Opening TLS socket")
    if ":" in resolver_str:
        domain = resolver_str.split(":", 1)[0]
        log_info("dns_transport::tls", "Connecting using domain %s" % rust_debug_str(domain))
        port_text = resolver_str.rsplit(":", 1)[1]
        port = _parse_rust_u16(port_text)
        if port is None:
            kind = _rust_u16_error_kind(port_text, 10)
            rust_panic("dns-transport/src/tls.rs:41:65",
                       "Invalid port number: ParseIntError { kind: %s }" % kind)
    else:
        domain = resolver_str
        log_info("dns_transport::tls", "Connecting using domain %s" % rust_debug_str(domain))
        port = 853
    addresses = _host_port_to_addresses(domain, port)
    raw_sock = _connect_stream(addresses)
    tls_sock = _tls_connect(raw_sock, domain)
    try:
        log_debug("dns_transport::tls", "Connected")
        payload = struct.pack("!H", len(packet)) + packet
        log_info("dns_transport::tls", "Sending %d bytes of data to %s over TLS" % (len(payload), resolver_str))
        try:
            tls_sock.sendall(payload)
        except Exception as exc:
            if isinstance(exc, ssl.SSLError):
                raise Failure("tls", _map_tls_error(exc))
            if isinstance(exc, OSError):
                raise _network_failure(exc)
            raise
        log_debug("dns_transport::tls", "Wrote all bytes")
        return _receive_tcp_stream(tls_sock, tls_stream=True)
    finally:
        try:
            tls_sock.close()
        except Exception:
            pass

