# Resolver / address handling
# ---------------------------------------------------------------------------

class SystemNameserverFailure(Failure):
    def __init__(self, message):
        Failure.__init__(self, "system", message)

def _os_error_message(exc):
    if getattr(exc, "errno", None) is not None:
        message = getattr(exc, "strerror", None) or os.strerror(exc.errno)
        return "%s (os error %d)" % (message, exc.errno)
    return str(exc)

def _network_failure(exc):
    if isinstance(exc, socket.gaierror):
        message = getattr(exc, "strerror", None) or str(exc)
        return Failure("network", "failed to lookup address information: %s" % message)
    if isinstance(exc, OSError):
        return Failure("network", _os_error_message(exc))
    return Failure("network", str(exc))

def get_system_nameserver():
    try:
        with open("/etc/resolv.conf", "rb") as handle:
            data = handle.read()
    except OSError as exc:
        raise SystemNameserverFailure(_os_error_message(exc))
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        text = data.decode("utf-8", "replace")
    for line in text.splitlines():
        # Strip comments commonly used in resolv.conf.
        stripped = line.strip()
        if not stripped or stripped.startswith("#") or stripped.startswith(";"):
            continue
        fields = stripped.split()
        if len(fields) >= 2 and fields[0] == "nameserver":
            return fields[1]
    raise SystemNameserverFailure("No nameserver found in /etc/resolv.conf")

