# HTTPS (DNS-over-HTTPS) ------------------------------------------------------

class _HttpResult(object):
    __slots__ = ("status", "error", "code", "reason", "headers", "header_length")
    def __init__(self, status, error=None, code=0, reason="", headers=None, header_length=0):
        self.status = status  # "complete" | "partial" | "error"
        self.error = error
        self.code = code
        self.reason = reason
        self.headers = headers or []
        self.header_length = header_length

_HTTP_TOKEN_CHARS = set(b"!#$%&'*+-.^_`|~0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz")

def _parse_http_response(data):
    length = len(data)
    # Version: only HTTP/1.0 and HTTP/1.1 are accepted by httparse here.
    versions = (b"HTTP/1.0", b"HTTP/1.1")
    if length < 8:
        for version in versions:
            if version.startswith(bytes(data)):
