                # Without a length, the body is delimited by the close of
                # the connection (or by running out of buffer space).
                continue
    log_info("dns_transport::https", "Received %d bytes of data" % len(buffer))
    result = _parse_http_response(buffer)
    if result.status == "error":
        raise Failure("http", result.error)
    if result.status != "complete":
        raise MalformedPacket("insufficient data")
    if result.code != 200:
        raise Failure("http", "Nameserver returned HTTP %d (%s)" % (result.code, result.reason))
    for name, value in result.headers:
        log_debug("dns_transport::https", "Header %s -> %s" % (rust_debug_str(name), rust_debug_str(value)))
    body = bytes(buffer[result.header_length:])
    content_length = _http_content_length(result.headers)
    if content_length is not None and len(body) < content_length:
        raise MalformedPacket("insufficient data")
    log_debug("dns_transport::https", "HTTP body has %d bytes" % len(body))
    return body

def _panic_invalid_https_nameserver():
    rust_panic("dns-transport/src/https.rs:42:50", "Invalid HTTPS nameserver")

def send_over_https(packet, resolver):
    resolver_str = resolve_resolver_string(resolver)
    if not resolver_str.startswith("https://"):
        _panic_invalid_https_nameserver()
    rest = resolver_str[len("https://"):]
    slash = rest.find("/")
    if slash < 0:
        _panic_invalid_https_nameserver()
    authority = rest[:slash]
    path = rest[slash:]

    log_info("dns_transport::https", "Opening TLS socket to %s" % rust_debug_str(authority))
    addresses = _host_port_to_addresses(authority, 443)
    raw_sock = _connect_stream(addresses)
    tls_sock = _tls_connect(raw_sock, authority)
    try:
        log_debug("dns_transport::https", "Connected")
        request_head = (
            "POST %s HTTP/1.1\r\n"
            "Host: %s\r\n"
            "Content-Type: application/dns-message\r\n"
            "Accept: application/dns-message\r\n"
            "User-Agent: dog/0.2.0-pre\r\n"
            "Content-Length: %d\r\n"
            "\r\n" % (path, authority, len(packet))
        ).encode("utf-8", "surrogateescape")
        request_bytes = request_head + packet
        log_info(
            "dns_transport::https",
            "Sending %d bytes of data to %s over HTTPS" % (len(request_bytes), rust_debug_str(resolver_str)),
        )
        try:
            tls_sock.sendall(request_bytes)
        except Exception as exc:
            if isinstance(exc, ssl.SSLError):
                raise Failure("tls", _map_tls_error(exc))
            if isinstance(exc, OSError):
                raise _network_failure(exc)
            raise
        log_debug("dns_transport::https", "Wrote all bytes")
        return _receive_https(tls_sock)
    finally:
        try:
            tls_sock.close()
        except Exception:
            pass

# Dispatch ---------------------------------------------------------------------

def execute_request(packet, resolver, transport):
    if transport == "automatic":
        data = send_over_udp(packet, resolver)
        response = parse_response(data)
        if response.truncated:
            log_debug("dns_transport::auto", "Truncated flag set, so switching to TCP")
            tcp_data = send_over_tcp(packet, resolver)
            response = parse_response(tcp_data)
        return response
    if transport == "udp":
        return parse_response(send_over_udp(packet, resolver))
    if transport == "tcp":
        return parse_response(send_over_tcp(packet, resolver))
    if transport == "tls":
        return parse_response(send_over_tls(packet, resolver))
    if transport == "https":
        return parse_response(send_over_https(packet, resolver))
    raise AssertionError("unknown transport %r" % transport)

