        out.append("Ran in %dms\n" % elapsed_ms)
    if out:
        out_write("".join(out))

def _json_escape(text):
    out = ['"']
    for ch in text:
        if ch == '"':
            out.append('\\"')
        elif ch == "\\":
            out.append("\\\\")
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\r":
            out.append("\\r")
        elif ch == "\t":
            out.append("\\t")
        elif ch == "\b":
            out.append("\\b")
        elif ch == "\f":
            out.append("\\f")
        elif ord(ch) < 0x20:
            out.append("\\u%04x" % ord(ch))
        else:
            out.append(ch)
    out.append('"')
    return "".join(out)

def json_compact(value):
    if value is None:
        return "null"
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, str):
        return _json_escape(value)
    if isinstance(value, (list, tuple)):
        return "[" + ",".join(json_compact(item) for item in value) + "]"
    if isinstance(value, dict):
        return "{" + ",".join(_json_escape(str(key)) + ":" + json_compact(item) for key, item in value.items()) + "}"
    raise TypeError("unsupported JSON value %r" % (value,))

