    if kind == "HINFO":
        return {"cpu": lossy_utf8(data["cpu"]), "os": lossy_utf8(data["os"])}
    if kind == "MX":
        return {"preference": data["preference"], "exchange": str(data["labels"])}
    if kind == "TXT":
        return {"messages": [lossy_utf8(message) for message in data["messages"]]}
    if kind == "SOA":
        return {"mname": str(data["mname"])}
    if kind == "SRV":
        return {"priority": data["priority"], "weight": data["weight"],
                "port": data["port"], "target": str(data["labels"])}
    if kind == "CAA":
        return {"critical": data["critical"], "tag": lossy_utf8(data["tag"]),
                "value": lossy_utf8(data["value"])}
    if kind == "LOC":
        return {
            "size": "%de%d" % (data["size"] >> 4, data["size"] & 15),
            "precision": {"horizontal": data["horiz"], "vertical": data["vert"]},
            "point": {
                "latitude": _loc_coordinate(data["latitude"], True),
                "longitude": _loc_coordinate(data["longitude"], False),
                "altitude": _loc_altitude(data["altitude"]),
