    if kind == "TLSA":
        return {"certificate_usage": data["certificate_usage"], "selector": data["selector"],
                "matching_type": data["matching_type"], "certificate_data": data["certificate_data"]}
    if kind == "OPENPGPKEY":
        return {"key": data["key"]}
