def record_json(record):
    if record.is_opt:
        return {
            "name": str(record.name),
            "type": "OPT",
            "data": {"version": record.opt_version, "data": list(record.opt_data)},
        }
    return {
        "name": str(record.name),
        "class": class_display(record.class_code),
        "ttl": record.ttl,
        "type": type_display(record.type_code),
        "data": record_data_json(record),
    }

def print_json_output(responses, options, elapsed=None):
    response_items = []
    for response in responses:
        response_items.append({
            "queries": [
                {"name": str(query.name), "class": class_display(query.class_code),
                 "type": type_display(query.type_code)}
                for query in response.queries
            ],
            "answers": [record_json(record) for record in _filtered_records(response.answers, options)],
            "authorities": [record_json(record) for record in _filtered_records(response.authorities, options)],
            "additionals": [record_json(record) for record in _filtered_records(response.additionals, options)],
        })
    obj = {"responses": response_items}
    if options.measure_time and elapsed is not None:
        secs, millis = elapsed
        obj["duration"] = {"secs": secs, "millis": millis}
