def print_text_output(responses, options, elapsed_ms=None):
    out = []
    for response in responses:
        if response.error_code != 0:
            status_text = _RCODE_TEXT.get(
                response.error_code, "Other Failure (%d)" % response.error_code)
            out.append("Status: %s\n" % status_text)

    rows = []
    for response in responses:
        for section_name, marker in (("answers", " "), ("authorities", "A"), ("additionals", "+")):
            for record in _filtered_records(getattr(response, section_name), options):
                type_str = "OPT" if record.is_opt else type_text(record.type_code)
                name_str = str(record.name)
                ttl_str = "" if record.is_opt else format_duration(record.ttl, options.format_durations)
                summary = record_data_summary(record, options.format_durations)
                rows.append((record, type_str, name_str, ttl_str, marker, summary))

    if rows:
        type_width = max(_byte_len(row[1]) for row in rows)
        name_width = max(_byte_len(row[2]) for row in rows)
        ttl_width = max(_byte_len(row[3]) for row in rows)
        use_colour = should_use_colour(options.colour_choice)
        for record, type_str, name_str, ttl_str, marker, summary in rows:
            type_padding = " " * (type_width - _byte_len(type_str))
            name_padding = " " * (name_width - _byte_len(name_str))
            ttl_padding = " " * (ttl_width - _byte_len(ttl_str))
            if use_colour:
                type_colour = "35" if record.is_opt else _TYPE_COLOURS.get(record.type_code, "41;37")
                type_part = type_padding + _paint(type_colour, type_str)
                name_part = _paint("1;34", name_str) + name_padding
                if marker == "A":
                    marker_part = _paint("36", marker)
                elif marker == "+":
                    marker_part = _paint("32", marker)
                else:
                    marker_part = marker
            else:
                type_part = type_padding + type_str
                name_part = name_str + name_padding
                marker_part = marker
            out.append("%s %s %s%s %s %s\n" % (type_part, name_part, ttl_padding, ttl_str, marker_part, summary))
    if options.measure_time and elapsed_ms is not None:
        out.append("Ran in %dms\n" % elapsed_ms)
    if out:
        out_write("".join(out))

def _json_escape(text):
    out = ['"']
    for ch in text:
        if ch == '"':
            out.append('\\"')
        elif ch == "\\":
            out.append("\\\\")
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\r":
            out.append("\\r")
        elif ch == "\t":
            out.append("\\t")
        elif ch == "\b":
            out.append("\\b")
        elif ch == "\f":
            out.append("\\f")
        elif ord(ch) < 0x20:
            out.append("\\u%04x" % ord(ch))
        else:
            out.append(ch)
    out.append('"')
    return "".join(out)

def json_compact(value):
    if value is None:
        return "null"
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, str):
        return _json_escape(value)
    if isinstance(value, (list, tuple)):
        return "[" + ",".join(json_compact(item) for item in value) + "]"
    if isinstance(value, dict):
        return "{" + ",".join(_json_escape(str(key)) + ":" + json_compact(item) for key, item in value.items()) + "}"
    raise TypeError("unsupported JSON value %r" % (value,))

