            lines.append(record_data_summary(record, options.format_durations) + "\n")
    if lines:
        out_write("".join(lines))
    return len(lines)

# Hosts-file hints ------------------------------------------------------------

def load_hosts_hints():
    log_debug("dog::hints", "Reading hints from /etc/hosts")
    hints = set()
    try:
        with open("/etc/hosts", "rb") as handle:
            raw = handle.read()
    except OSError:
        log_trace("dog::hints", "0 hostname hints loaded OK.")
        return hints
    text = raw.decode("utf-8", "replace")
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        tokens = stripped.split()
        if len(tokens) < 2:
            continue
        for token in tokens[1:]:
            if token.startswith("#"):
                break
            try:
                hints.add(encode_labels(token))
            except OptionsError:
                continue
    log_trace("dog::hints", "%d hostname hints loaded OK." % len(hints))
    return hints

# Main -------------------------------------------------------------------------

def _print_failure(failure, options):
    if options is not None and options.format_mode == "json":
        err_write(json_compact({
            "error": True,
            "error_phase": failure.phase,
            "error_message": failure.message,
        }) + "\n")
    else:
        err_write("Error [%s]: %s\n" % (failure.phase, failure.message))

def run(argv_bytes):
    setup_logging()
    try:
        signal.signal(signal.SIGINT, signal.SIG_DFL)
    except Exception:
        pass

    argv = []
    for raw_arg in argv_bytes:
        try:
            argv.append(raw_arg.decode("utf-8"))
        except UnicodeDecodeError:
            err_write("dog: Invalid options: Unrecognized option: '%s'\n" % rust_debug_osstring(raw_arg))
            return 3

    try:
        parsed = parse_options(argv)
    except (GetoptsFail, OptionsError) as exc:
        err_write("dog: Invalid options: %s\n" % exc)
        return 3

    if parsed.kind == "version":
        print_version_text(parsed.colour_choice)
        return 0
    if parsed.kind == "help":
        print_help_text(parsed.colour_choice)
        return 0
    if parsed.kind == "nodomains":
        print_help_text(parsed.colour_choice)
        return 3

    options = parsed.options
    if log_enabled("INFO"):
        log_info("dog", "Running with options -> %s" % rust_debug_pretty(options.debug_node()))

    hints = load_hosts_hints()
    for domain in options.domains:
        if domain in hints:
            err_write("warning: domain '%s' also exists in hosts file\n" % domain)

    start_ns = time.monotonic_ns() if options.measure_time else None
    responses = []
    had_failure = False
    system_failure = False
    random_generator = random.SystemRandom()

    for domain in options.domains:
        for type_code in options.record_types:
            for class_code in options.classes:
                for resolver in options.resolvers:
                    for transport in options.transport_types:
                        txid = options.txid if options.txid is not None else random_generator.getrandbits(16)
                        packet = build_request_packet(options, domain, type_code, class_code, txid)
                        try:
                            response = execute_request(packet, resolver, transport)
                        except SystemNameserverFailure as failure:
                            system_failure = True
                            had_failure = True
                            _print_failure(failure, options)
                        except MalformedPacket as exc:
                            had_failure = True
                            _print_failure(Failure("protocol", exc.message), options)
                        except Failure as failure:
                            if isinstance(failure, SystemNameserverFailure):
                                system_failure = True
                            had_failure = True
                            _print_failure(failure, options)
                        except OSError as exc:
                            had_failure = True
                            _print_failure(_network_failure(exc), options)
                        else:
                            responses.append(response)

    elapsed = None
    elapsed_ms = None
    if start_ns is not None:
        elapsed_ns = time.monotonic_ns() - start_ns
        elapsed = (elapsed_ns // 1000000000, (elapsed_ns // 1000000) % 1000)
        elapsed_ms = elapsed_ns // 1000000

    answer_count = 0
    for response in responses:
        answer_count += len(_filtered_records(response.answers, options))

    if options.format_mode == "json":
        print_json_output(responses, options, elapsed)
    elif options.format_mode == "short":
        print_short_output(responses, options)
    else:
        print_text_output(responses, options, elapsed_ms)

    if options.format_mode == "short" and answer_count == 0:
        err_write("No results\n")
        if system_failure:
            return 4
        return 2
    if system_failure:
        return 4
    if had_failure:
        return 1
    return 0

def main():
    argv_bytes = [os.fsencode(arg) for arg in sys.argv[1:]]
    try:
        status = run(argv_bytes)
    except BrokenPipeError:
        status = 1
    sys.exit(status)

if __name__ == "__main__":
    main()
