def format_duration(seconds, format_durations=True):
    if not format_durations:
        return str(seconds)
    days, remainder = divmod(seconds, 86400)
    hours, remainder = divmod(remainder, 3600)
    minutes, secs = divmod(remainder, 60)
    if days:
        return "%dd%dh%02dm%02ds" % (days, hours, minutes, secs)
    if hours:
        return "%dh%02dm%02ds" % (hours, minutes, secs)
    if minutes:
        return "%dm%02ds" % (minutes, secs)
    return "%ds" % secs

def _loc_coordinate(raw, is_latitude):
    offset = raw - (1 << 31)
    limit = (90 if is_latitude else 180) * 3600 * 1000
    if abs(offset) > limit:
        return None
    if is_latitude:
        direction = "N" if offset >= 0 else "S"
    else:
        direction = "E" if offset >= 0 else "W"
    total = abs(offset)
    degrees, remainder = divmod(total, 3600000)
    minutes, remainder = divmod(remainder, 60000)
    seconds, millis = divmod(remainder, 1000)
    if millis:
        return "%d\u00b0%d\u2032%d.%03d\u2033 %s" % (degrees, minutes, seconds, millis, direction)
    return "%d\u00b0%d\u2032%d\u2033 %s" % (degrees, minutes, seconds, direction)

def _loc_altitude(raw):
    centis = raw - 10000000
    whole = abs(centis) // 100
    if centis < 0:
        whole = -whole
    remainder = centis - whole * 100
    if remainder == 0:
        return "%dm" % whole
    return "%d.%dm" % (whole, remainder)

