                "port": data["port"], "target": str(data["labels"])}
    if kind == "CAA":
        return {"critical": data["critical"], "tag": lossy_utf8(data["tag"]),
                "value": lossy_utf8(data["value"])}
    if kind == "LOC":
        return {
            "size": "%de%d" % (data["size"] >> 4, data["size"] & 15),
            "precision": {"horizontal": data["horiz"], "vertical": data["vert"]},
            "point": {
                "latitude": _loc_coordinate(data["latitude"], True),
                "longitude": _loc_coordinate(data["longitude"], False),
                "altitude": _loc_altitude(data["altitude"]),
            },
        }
    if kind == "NAPTR":
        return {"order": data["order"], "flags": lossy_utf8(data["flags"]),
                "service": lossy_utf8(data["service"]), "regex": lossy_utf8(data["regex"]),
                "replacement": str(data["labels"])}
    if kind == "SSHFP":
        return {"algorithm": data["algorithm"], "fingerprint_type": data["fingerprint_type"],
                "fingerprint": data["fingerprint"]}
    if kind == "TLSA":
        return {"certificate_usage": data["certificate_usage"], "selector": data["selector"],
                "matching_type": data["matching_type"], "certificate_data": data["certificate_data"]}
    if kind == "OPENPGPKEY":
        return {"key": data["key"]}
    if kind in ("EUI48", "EUI64"):
        return {"identifier": data["identifier"]}
    if kind == "URI":
        return {"priority": data["priority"], "weight": data["weight"],
                "target": lossy_utf8(data["target"])}
    return {"bytes": list(data["bytes"])}

def record_json(record):
    if record.is_opt:
        return {
            "name": str(record.name),
            "type": "OPT",
            "data": {"version": record.opt_version, "data": list(record.opt_data)},
        }
    return {
        "name": str(record.name),
        "class": class_display(record.class_code),
        "ttl": record.ttl,
        "type": type_display(record.type_code),
        "data": record_data_json(record),
    }

def print_json_output(responses, options, elapsed=None):
    response_items = []
    for response in responses:
        response_items.append({
            "queries": [
                {"name": str(query.name), "class": class_display(query.class_code),
                 "type": type_display(query.type_code)}
                for query in response.queries
            ],
            "answers": [record_json(record) for record in _filtered_records(response.answers, options)],
            "authorities": [record_json(record) for record in _filtered_records(response.authorities, options)],
            "additionals": [record_json(record) for record in _filtered_records(response.additionals, options)],
        })
    obj = {"responses": response_items}
    if options.measure_time and elapsed is not None:
        secs, millis = elapsed
        obj["duration"] = {"secs": secs, "millis": millis}
    out_write(json_compact(obj) + "\n")

def print_short_output(responses, options):
    lines = []
    for response in responses:
        for record in _filtered_records(response.answers, options):
            lines.append(record_data_summary(record, options.format_durations) + "\n")
    if lines:
        out_write("".join(lines))
    return len(lines)

# Hosts-file hints ------------------------------------------------------------

def load_hosts_hints():
    log_debug("dog::hints", "Reading hints from /etc/hosts")
    hints = set()
    try:
        with open("/etc/hosts", "rb") as handle:
            raw = handle.read()
    except OSError:
        log_trace("dog::hints", "0 hostname hints loaded OK.")
        return hints
    text = raw.decode("utf-8", "replace")
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        tokens = stripped.split()
        if len(tokens) < 2:
            continue
        for token in tokens[1:]:
            if token.startswith("#"):
                break
            try:
                hints.add(encode_labels(token))
            except OptionsError:
                continue
    log_trace("dog::hints", "%d hostname hints loaded OK." % len(hints))
    return hints

# Main -------------------------------------------------------------------------

def _print_failure(failure, options):
    if options is not None and options.format_mode == "json":
        err_write(json_compact({
            "error": True,
            "error_phase": failure.phase,
            "error_message": failure.message,
        }) + "\n")
    else:
        err_write("Error [%s]: %s\n" % (failure.phase, failure.message))

def run(argv_bytes):
    setup_logging()
    try:
        signal.signal(signal.SIGINT, signal.SIG_DFL)
    except Exception:
        pass

    argv = []
    for raw_arg in argv_bytes:
        try:
            argv.append(raw_arg.decode("utf-8"))
        except UnicodeDecodeError:
            err_write("dog: Invalid options: Unrecognized option: '%s'\n" % rust_debug_osstring(raw_arg))
            return 3

    try:
        parsed = parse_options(argv)
    except (GetoptsFail, OptionsError) as exc:
        err_write("dog: Invalid options: %s\n" % exc)
        return 3

    if parsed.kind == "version":
        print_version_text(parsed.colour_choice)
        return 0
    if parsed.kind == "help":
        print_help_text(parsed.colour_choice)
        return 0
    if parsed.kind == "nodomains":
        print_help_text(parsed.colour_choice)
        return 3

    options = parsed.options
    if log_enabled("INFO"):
        log_info("dog", "Running with options -> %s" % rust_debug_pretty(options.debug_node()))

    hints = load_hosts_hints()
    for domain in options.domains:
        if domain in hints:
            err_write("warning: domain '%s' also exists in hosts file\n" % domain)

    start_ns = time.monotonic_ns() if options.measure_time else None
    responses = []
    had_failure = False
    system_failure = False
    random_generator = random.SystemRandom()

    for domain in options.domains:
        for type_code in options.record_types:
            for class_code in options.classes:
                for resolver in options.resolvers:
                    for transport in options.transport_types:
                        txid = options.txid if options.txid is not None else random_generator.getrandbits(16)
                        packet = build_request_packet(options, domain, type_code, class_code, txid)
                        try:
                            response = execute_request(packet, resolver, transport)
                        except SystemNameserverFailure as failure:
                            system_failure = True
                            had_failure = True
                            _print_failure(failure, options)
                        except MalformedPacket as exc:
                            had_failure = True
                            _print_failure(Failure("protocol", exc.message), options)
                        except Failure as failure:
                            if isinstance(failure, SystemNameserverFailure):
                                system_failure = True
                            had_failure = True
                            _print_failure(failure, options)
                        except OSError as exc:
                            had_failure = True
                            _print_failure(_network_failure(exc), options)
                        else:
                            responses.append(response)

    elapsed = None
    elapsed_ms = None
    if start_ns is not None:
        elapsed_ns = time.monotonic_ns() - start_ns
        elapsed = (elapsed_ns // 1000000000, (elapsed_ns // 1000000) % 1000)
        elapsed_ms = elapsed_ns // 1000000

    answer_count = 0
    for response in responses:
        answer_count += len(_filtered_records(response.answers, options))

    if options.format_mode == "json":
        print_json_output(responses, options, elapsed)
    elif options.format_mode == "short":
        print_short_output(responses, options)
    else:
        print_text_output(responses, options, elapsed_ms)

    if options.format_mode == "short" and answer_count == 0:
        err_write("No results\n")
        if system_failure:
            return 4
        return 2
    if system_failure:
        return 4
    if had_failure:
        return 1
    return 0

def main():
    argv_bytes = [os.fsencode(arg) for arg in sys.argv[1:]]
    try:
        status = run(argv_bytes)
    except BrokenPipeError:
        status = 1
    sys.exit(status)

if __name__ == "__main__":
    main()
