class Labels(object):
    __slots__ = ("segments", "segment_lengths")

    def __init__(self, segments, segment_lengths=None):
        self.segments = tuple(segments)
        if segment_lengths is None:
            segment_lengths = [len(segment.encode("utf-8", "surrogateescape")) for segment in self.segments]
        self.segment_lengths = tuple(segment_lengths)

    def __str__(self):
        return "".join(segment + "." for segment in self.segments)

    def __repr__(self):
        return "Labels(%r)" % (self.segments,)

    def __eq__(self, other):
        return isinstance(other, Labels) and self.segments == other.segments

    def __hash__(self):
        return hash(self.segments)

    def debug_node(self):
        segment_nodes = [
            _Tuple([self.segment_lengths[index], segment])
            for index, segment in enumerate(self.segments)
        ]
        return _Struct("Labels", [("segments", _List(segment_nodes))])

    def compact_debug(self):
        parts = [
            "(%d, %s)" % (self.segment_lengths[index], rust_debug_str(segment))
            for index, segment in enumerate(self.segments)
        ]
        return "Labels { segments: [%s] }" % ", ".join(parts)

    def wire_bytes(self):
        out = bytearray()
        for segment in self.segments:
            raw = segment.encode("utf-8", "surrogateescape")
            out.append(len(raw))
            out.extend(raw)
        out.append(0)
        return bytes(out)

