            for index, segment in enumerate(self.segments)
        ]
        return "Labels { segments: [%s] }" % ", ".join(parts)

    def wire_bytes(self):
        out = bytearray()
        for segment in self.segments:
            raw = segment.encode("utf-8", "surrogateescape")
            out.append(len(raw))
            out.extend(raw)
        out.append(0)
